from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])

    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1

    # BFS 1: shortest walk distance from (0, 0)
    d1 = [[-1] * C for _ in range(R)]
    d1[0][0] = 0
    q = deque([(0, 0)])
    while q:
        r, col = q.popleft()
        dist = d1[r][col]
        for nr, nc in ((r + 1, col), (r - 1, col), (r, col + 1), (r, col - 1)):
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and d1[nr][nc] == -1:
                d1[nr][nc] = dist + 1
                q.append((nr, nc))

    # BFS 2: shortest walk distance from (R - 1, C - 1)
    d2 = [[-1] * C for _ in range(R)]
    d2[R - 1][C - 1] = 0
    q = deque([(R - 1, C - 1)])
    while q:
        r, col = q.popleft()
        dist = d2[r][col]
        for nr, nc in ((r + 1, col), (r - 1, col), (r, col + 1), (r, col - 1)):
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and d2[nr][nc] == -1:
                d2[nr][nc] = dist + 1
                q.append((nr, nc))

    ans = d1[R - 1][C - 1] if d1[R - 1][C - 1] != -1 else float('inf')

    # Collect the top 2 best d1 and top 2 best d2 cells for each label
    best1 = {}
    best2 = {}

    for r in range(R):
        for col in range(C):
            lbl = grid[r][col]
            if lbl == -1:
                continue

            # Update best two cells reachable from start
            v1 = d1[r][col]
            if v1 != -1:
                pt = (r, col)
                if lbl not in best1:
                    best1[lbl] = [(v1, pt)]
                else:
                    b = best1[lbl]
                    if len(b) < 2:
                        b.append((v1, pt))
                        b.sort()
                    elif v1 < b[1][0]:
                        b[1] = (v1, pt)
                        b.sort()

            # Update best two cells that can reach the target
            v2 = d2[r][col]
            if v2 != -1:
                pt = (r, col)
                if lbl not in best2:
                    best2[lbl] = [(v2, pt)]
                else:
                    b = best2[lbl]
                    if len(b) < 2:
                        b.append((v2, pt))
                        b.sort()
                    elif v2 < b[1][0]:
                        b[1] = (v2, pt)
                        b.sort()

    # Consider teleporting between distinct cells of the same label
    for lbl, cands1 in best1.items():
        if lbl in best2:
            cands2 = best2[lbl]
            for v1, p1 in cands1:
                for v2, p2 in cands2:
                    if p1 != p2:
                        cost = v1 + v2 + c
                        if cost < ans:
                            ans = cost

    return ans if ans != float('inf') else -1

def smallest_balanced(s: str) -> str:
    n = len(s)
    if n % 2 != 0:
        raise ValueError("Odd-length string cannot be balanced.")

    target = n // 2
    fixed_open = s.count('(')
    fixed_close = s.count(')')

    if fixed_open > target or fixed_close > target:
        raise ValueError("Too many fixed parentheses to balance.")

    rem_open = target - fixed_open

    # Greedily place '(' at the earliest '?' positions
    res = []
    for ch in s:
        if ch == '?':
            if rem_open > 0:
                res.append('(')
                rem_open -= 1
            else:
                res.append(')')
        else:
            res.append(ch)

    # Verify if the candidate string is valid
    balance = 0
    for ch in res:
        if ch == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            raise ValueError("String cannot be balanced.")

    if balance != 0:
        raise ValueError("String cannot be balanced.")

    return "".join(res)

def longest_spaced_repeat(s: str, gap: int) -> int:
    n = len(s)
    if n == 0 or gap >= n:
        return 0

    # dp[i][j] will store the length of the longest common prefix of s[i:] and s[j:]
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    ans = 0

    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
                diff = j - i - gap
                if diff > 0:
                    cand = dp[i][j] if dp[i][j] < diff else diff
                    if cand > ans:
                        ans = cand

    return ans

def min_insertions(s: str, allowed) -> int:
    n = len(s)
    if n <= 1:
        return 0

    allowed_set = set(allowed)
    INF = float("inf")

    # dp[i][j] stores the min insertions for substring s[i..j]
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            res = INF

            if s[i] == s[j]:
                res = min(res, dp[i + 1][j - 1] if i + 1 <= j - 1 else 0)
            if s[i] in allowed_set:
                res = min(res, dp[i + 1][j] + 1)
            if s[j] in allowed_set:
                res = min(res, dp[i][j - 1] + 1)

            dp[i][j] = res

    ans = dp[0][n - 1]
    return ans if ans != INF else -1

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

import re

_AMOUNT_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError("amount must be a string")

        match = _AMOUNT_RE.fullmatch(amount)
        if not match:
            raise ValueError(f"invalid amount format: {amount!r}")

        dollars, fraction = match.groups()
        cents = int(dollars) * 100 + int((fraction or "").ljust(2, "0"))
        if cents <= 0:
            raise ValueError("amount must be positive")

        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents

    return balances

from functools import wraps

def memoize(func):
    cache = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            wrapper.hits += 1
            return cache[key]
        wrapper.misses += 1
        result = func(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.hits = 0
    wrapper.misses = 0
    return wrapper

def apply_hunks(lines, hunks):
    for start, delete, insert in hunks:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")

    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        if ordered[i][0] == prev[0] or ordered[i][0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")

    result = []
    last_idx = 0
    for start, delete, insert in ordered:
        result.extend(lines[last_idx:start])
        result.extend(insert)
        last_idx = start + delete
    result.extend(lines[last_idx:])
    return result

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

def purge_expired(sessions, now):
    purged = [sid for sid, expiry in sessions.items() if expiry <= now]
    for sid in purged:
        del sessions[sid]
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

