class CountingBag:
    """A multiset (bag) of hashable items tracking counts and deterministic entry order."""

    def __init__(self):
        self._counts = {}
        self._entry_order = {}
        self._timer = 0
        self._total = 0

    def add(self, item) -> int:
        """Add one occurrence of item; return the item's new count."""
        self._total += 1
        if item in self._counts:
            self._counts[item] += 1
        else:
            self._counts[item] = 1
            self._timer += 1
            self._entry_order[item] = self._timer
        return self._counts[item]

    def discard(self, item) -> bool:
        """Remove one occurrence; return True if removed, False if absent."""
        if item not in self._counts:
            return False
        self._total -= 1
        self._counts[item] -= 1
        if self._counts[item] == 0:
            del self._counts[item]
            del self._entry_order[item]
        return True

    def count(self, item) -> int:
        """Return the current count of item (0 if absent)."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Return the total number of occurrences across all items."""
        return self._total

    def distinct(self) -> int:
        """Return the number of distinct items currently present (count >= 1)."""
        return len(self._counts)

    def most_common(self, k: int) -> list:
        """
        Return the k items with the highest counts as (item, count) tuples.
        Ordered by count descending; ties broken by earlier entry moment first.
        """
        if k < 0:
            raise ValueError(f"k must be non-negative, got {k}")
        if k == 0 or not self._counts:
            return []

        # Key: (-count, entry_timestamp)
        # Because each present item has a unique timestamp, ties in count
        # are broken strictly by entry order without comparing the items themselves.
        return heapq.nsmallest(
            k,
            self._counts.items(),
            key=lambda pair: (-pair[1], self._entry_order[pair[0]]),
        )

