from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("Capacity must be an integer >= 1")

        self._capacity = capacity
        self._cache = OrderedDict()  # key -> (value, expire_at, version)
        self._heap = []  # min-heap of (expire_at, key, version)
        self._version = 0

        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now: int | float) -> None:
        """Removes all entries that have expired at or before `now`."""
        while self._heap:
            expire_at, key, ver = self._heap[0]
            if expire_at > now:
                break
            heapq.heappop(self._heap)
            entry = self._cache.get(key)
            if entry is not None and entry[2] == ver:
                del self._cache[key]
                self._expirations += 1

    def put(self, key, value, now: int | float, ttl: int | float | None = None) -> None:
        if ttl is not None and ttl <= 0:
            raise ValueError("TTL must be a positive number")

        self._purge(now)

        self._version += 1
        expire_at = (now + ttl) if ttl is not None else None

        if key in self._cache:
            self._cache[key] = (value, expire_at, self._version)
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self._capacity:
                self._cache.popitem(last=False)
                self._evictions += 1
            self._cache[key] = (value, expire_at, self._version)

        if expire_at is not None:
            heapq.heappush(self._heap, (expire_at, key, self._version))

    def get(self, key, now: int | float):
        self._purge(now)

        if key in self._cache:
            self._hits += 1
            self._cache.move_to_end(key)
            return self._cache[key][0]

        self._misses += 1
        return None

    def stats(self) -> dict:
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self) -> int:
        return len(self._cache)

class _Node:
    __slots__ = ("key", "parent", "size", "val")

    def __init__(self, key, val):
        self.key = key
        self.parent = None
        self.size = 1
        self.val = val


class MergeLedger:
    def __init__(self):
        self._nodes = {}
        self._history = []
        self._num_components = 0

    def _find_node(self, node: _Node) -> _Node:
        curr = node
        while curr.parent is not None:
            curr = curr.parent
        return curr

    def add(self, x, value=0) -> None:
        """Create element x as a new singleton component with the given value."""
        if x in self._nodes:
            raise ValueError(f"Element {x!r} already exists")
        self._nodes[x] = _Node(x, value)
        self._num_components += 1

    def merge(self, a, b) -> bool:
        """Unite the components containing a and b.

        Return True if united, False if already together.
        """
        if a not in self._nodes:
            raise KeyError(a)
        if b not in self._nodes:
            raise KeyError(b)

        root_a = self._find_node(self._nodes[a])
        root_b = self._find_node(self._nodes[b])

        if root_a is root_b:
            return False

        # Union by size to keep tree depth O(log N) without path compression
        if root_a.size < root_b.size:
            root_a, root_b = root_b, root_a

        # Attach root_b under root_a
        root_b.parent = root_a
        root_a.size += root_b.size
        root_a.val += root_b.val

        self._history.append((root_a, root_b))
        self._num_components -= 1
        return True

    def same(self, a, b) -> bool:
        """Return True if a and b are in the same component."""
        if a not in self._nodes:
            raise KeyError(a)
        if b not in self._nodes:
            raise KeyError(b)
        return self._find_node(self._nodes[a]) is self._find_node(self._nodes[b])

    def component_size(self, x) -> int:
        """Return number of elements in x's component."""
        if x not in self._nodes:
            raise KeyError(x)
        return self._find_node(self._nodes[x]).size

    def component_value(self, x):
        """Return sum of current values of all elements in x's component."""
        if x not in self._nodes:
            raise KeyError(x)
        return self._find_node(self._nodes[x]).val

    def add_value(self, x, delta) -> None:
        """Add delta to element x's value, updating component sum."""
        if x not in self._nodes:
            raise KeyError(x)

        curr = self._nodes[x]
        while curr is not None:
            curr.val += delta
            curr = curr.parent

    def components(self) -> int:
        """Return current number of components."""
        return self._num_components

    def undo(self) -> None:
        """Reverse the most recent successful merge."""
        if not self._history:
            raise RuntimeError("No merge to undo")

        root_a, root_b = self._history.pop()
        root_a.size -= root_b.size
        root_a.val -= root_b.val
        root_b.parent = None
        self._num_components += 1

