class IntervalSet:
    def __init__(self):
        # Stored as a list of [lo, hi] lists, kept sorted, pairwise disjoint, and non-adjacent.
        self._intervals = []
        self._total = 0

    def add(self, lo: int, hi: int) -> None:
        """Cover every integer in [lo, hi). Coalesces overlapping and adjacent intervals."""
        if lo >= hi:
            raise ValueError(f"Invalid interval: lo ({lo}) must be strictly less than hi ({hi})")

        # Find all intervals that overlap or touch [lo, hi).
        # An interval [l, r) touches or overlaps [lo, hi) iff r >= lo and l <= hi.
        # Find first interval where r >= lo:
        idx_left = self._bisect_first_touching_left(lo)
        # Find last interval where l <= hi:
        idx_right = self._bisect_last_touching_right(hi)

        if idx_left <= idx_right:
            # Coalesce with existing intervals
            new_lo = min(lo, self._intervals[idx_left][0])
            new_hi = max(hi, self._intervals[idx_right][1])

            # Update total
            removed_len = sum(r - l for l, r in self._intervals[idx_left : idx_right + 1])
            self._intervals[idx_left : idx_right + 1] = [[new_lo, new_hi]]
            self._total += (new_hi - new_lo) - removed_len
        else:
            # Insert as a brand-new interval at idx_left
            self._intervals.insert(idx_left, [lo, hi])
            self._total += hi - lo

    def remove(self, lo: int, hi: int) -> None:
        """Uncover every integer in [lo, hi). Splits intervals if necessary."""
        if lo >= hi:
            raise ValueError(f"Invalid interval: lo ({lo}) must be strictly less than hi ({hi})")

        # An interval [l, r) overlaps [lo, hi) iff r > lo and l < hi.
        idx_left = self._bisect_first_overlap_left(lo)
        idx_right = self._bisect_last_overlap_right(hi)

        if idx_left <= idx_right:
            new_pieces = []
            first_l = self._intervals[idx_left][0]
            last_r = self._intervals[idx_right][1]

            if first_l < lo:
                new_pieces.append([first_l, lo])
            if last_r > hi:
                new_pieces.append([hi, last_r])

            removed_len = sum(r - l for l, r in self._intervals[idx_left : idx_right + 1])
            added_len = sum(r - l for l, r in new_pieces)

            self._intervals[idx_left : idx_right + 1] = new_pieces
            self._total += added_len - removed_len

    def contains(self, x: int) -> bool:
        """Return whether the integer x is covered."""
        # Find the interval with largest l <= x
        idx = bisect.bisect_right(self._intervals, x, key=lambda iv: iv[0]) - 1
        if idx >= 0:
            l, r = self._intervals[idx]
            return l <= x < r
        return False

    def total(self) -> int:
        """Return the total number of integers covered."""
        return self._total

    def intervals(self) -> list:
        """Return the covered set as a sorted list of disjoint (lo, hi) tuples."""
        return [(l, r) for l, r in self._intervals]

    def gaps(self, lo: int, hi: int) -> list:
        """Return maximal uncovered sub-intervals in [lo, hi) as sorted (a, b) tuples."""
        if lo >= hi:
            raise ValueError(f"Invalid window: lo ({lo}) must be strictly less than hi ({hi})")

        gaps_list = []
        curr = lo

        # Only iterate over intervals that can overlap [lo, hi)
        start_idx = self._bisect_first_overlap_left(lo)
        for i in range(start_idx, len(self._intervals)):
            l, r = self._intervals[i]
            if l >= hi:
                break
            if l > curr:
                gaps_list.append((curr, min(l, hi)))
            curr = max(curr, r)
            if curr >= hi:
                break

        if curr < hi:
            gaps_list.append((curr, hi))

        return gaps_list

    # --- Binary search helpers ---

    def _bisect_first_touching_left(self, lo: int) -> int:
        """First index where interval.r >= lo."""
        left, right = 0, len(self._intervals)
        while left < right:
            mid = (left + right) // 2
            if self._intervals[mid][1] >= lo:
                right = mid
            else:
                left = mid + 1
        return left

    def _bisect_last_touching_right(self, hi: int) -> int:
        """Last index where interval.l <= hi."""
        left, right = 0, len(self._intervals)
        while left < right:
            mid = (left + right) // 2
            if self._intervals[mid][0] <= hi:
                left = mid + 1
            else:
                right = mid
        return left - 1

    def _bisect_first_overlap_left(self, lo: int) -> int:
        """First index where interval.r > lo."""
        left, right = 0, len(self._intervals)
        while left < right:
            mid = (left + right) // 2
            if self._intervals[mid][1] > lo:
                right = mid
            else:
                left = mid + 1
        return left

    def _bisect_last_overlap_right(self, hi: int) -> int:
        """Last index where interval.l < hi."""
        left, right = 0, len(self._intervals)
        while left < right:
            mid = (left + right) // 2
            if self._intervals[mid][0] < hi:
                left = mid + 1
            else:
                right = mid
        return left - 1

class UndoStack:
    def __init__(self) -> None:
        self._stack = []
        self._history = []

    def push(self, x) -> None:
        """Push x onto the top of the stack."""
        self._stack.append(x)
        self._history.append(('push', None))

    def pop(self):
        """Remove and return the top value. Raise IndexError if empty."""
        if not self._stack:
            raise IndexError("pop from empty stack")
        val = self._stack.pop()
        self._history.append(('pop', val))
        return val

    def peek(self):
        """Return the top value without removing it. Raise IndexError if empty."""
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def undo(self) -> None:
        """Reverse the most recent mutating operation that has not been undone."""
        if not self._history:
            raise RuntimeError("nothing left to undo")
        op, val = self._history.pop()
        if op == 'push':
            self._stack.pop()
        else:  # op == 'pop'
            self._stack.append(val)

    def __len__(self) -> int:
        """Number of values currently on the stack."""
        return len(self._stack)

from typing import Any, Hashable


class VersionedKV:
    """A key-value store with commit snapshots, point-in-time reads, and rollback."""

    def __init__(self) -> None:
        self._working: dict[Hashable, Any] = {}
        # Index 0 represents the empty initial state (version 0).
        self._snapshots: list[dict[Hashable, Any]] = [{}]

    def set(self, key: Hashable, value: Any) -> None:
        """Write to the working state."""
        self._working[key] = value

    def delete(self, key: Hashable) -> None:
        """Remove a key from the working state; raise KeyError if absent."""
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key: Hashable) -> Any:
        """Read a key from the working state; raise KeyError if absent."""
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key: Hashable) -> bool:
        """Check if a key is present in the working state."""
        return key in self._working

    def commit(self) -> int:
        """Snapshot the working state and return the new version number."""
        self._snapshots.append(self._working.copy())
        return self.latest()

    def get_at(self, key: Hashable, version: int) -> Any:
        """Return the key's value in snapshot `version`.

        Raises:
            ValueError: If version is not in range 1 <= version <= latest().
            KeyError: If the snapshot exists but does not contain the key.
        """
        if not isinstance(version, int) or isinstance(version, bool) or not (1 <= version <= self.latest()):
            raise ValueError(f"Version must be between 1 and {self.latest()}, got {version!r}")

        snapshot = self._snapshots[version]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version: int) -> None:
        """Replace the working state with a copy of snapshot `version` (version 0 = empty store).

        Raises:
            ValueError: If version is not in range 0 <= version <= latest().
        """
        if not isinstance(version, int) or isinstance(version, bool) or not (0 <= version <= self.latest()):
            raise ValueError(f"Version must be between 0 and {self.latest()}, got {version!r}")

        self._working = self._snapshots[version].copy()

    def latest(self) -> int:
        """Return the number of commits so far (0 if none)."""
        return len(self._snapshots) - 1

import math


def rank_scores(scores: list) -> list[int]:
    """Assign competition ranks ("1224" ranking) to a list of numeric scores.

    Higher scores receive better ranks (rank 1 is the best).
    Ties share a rank equal to 1 plus the number of scores strictly greater.
    """
    if not scores:
        return []

    # Validate that no scores are NaN
    for score in scores:
        if math.isnan(score):
            raise ValueError("Score cannot be NaN")

    # Sort indices by score in descending order
    # (stable sort preserves input order for equal values)
    indexed_scores = sorted(
        enumerate(scores), key=lambda item: item[1], reverse=True
    )

    ranks = [0] * len(scores)

    for rank_idx, (orig_idx, score) in enumerate(indexed_scores):
        if rank_idx > 0 and score == indexed_scores[rank_idx - 1][1]:
            # Equal score shares the rank of the previous entry
            ranks[orig_idx] = ranks[indexed_scores[rank_idx - 1][0]]
        else:
            # 1 + count of elements strictly greater (which is rank_idx)
            ranks[orig_idx] = rank_idx + 1

    return ranks

import unicodedata

_COMBINING_CATEGORIES = {'Mn', 'Mc', 'Me'}

def truncate_display(s: str, width: int) -> str:
    """Truncate a string to a maximum display width measured in user-perceived units.

    Combining marks (Unicode categories Mn, Mc, Me) add zero width and attach
    to the preceding character.
    """
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    units = 1  # The first code point always begins the first unit
    for i in range(1, len(s)):
        if unicodedata.category(s[i]) not in _COMBINING_CATEGORIES:
            units += 1
            if units > width:
                return s[:i]

    return s

def kth_root_floor(n: int, k: int) -> int:
    """Return the largest integer r >= 0 such that r ** k <= n."""
    if n < 0 or k < 1:
        raise ValueError("n must be non-negative and k must be at least 1.")

    if n == 0:
        return 0
    if k == 1 or n == 1:
        return n

    # If 2**k > n, then floor(n**(1/k)) is guaranteed to be 1 since n >= 1.
    bit_len = n.bit_length()
    if k >= bit_len:
        return 1

    # Exact upper bound: 2**(ceil(bit_len / k)) ** k >= 2**bit_len > n
    low = 1
    high = 1 << ((bit_len + k - 1) // k)
    ans = 1

    while low <= high:
        mid = (low + high) // 2
        if mid**k <= n:
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    return ans

from collections import deque
from typing import Any, Iterator


def round_robin(iterables: list) -> Iterator[Any]:
    iters = deque(iter(it) for it in iterables)
    while iters:
        it = iters.popleft()
        try:
            val = next(it)
        except StopIteration:
            continue
        iters.append(it)
        yield val

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if len(values) == 0:
        raise ValueError("values cannot be empty")

    for w in weights:
        if w < 0:
            raise ValueError("weights must be non-negative")

    W = sum(weights)
    if W <= 0:
        raise ValueError("total weight must be positive")

    # Sort pairs by value ascending
    pairs = sorted(zip(values, weights), key=lambda p: p[0])

    threshold = W / 2 - 1e-9
    c = 0.0
    for v, w in pairs:
        c += w
        if c >= threshold:
            return v

    return pairs[-1][0]

import math


def vector_norm(v: list[float]) -> float:
    """Compute the Euclidean (L2) norm of a vector of floats robustly."""
    for x in v:
        if not math.isfinite(x):
            raise ValueError(f"Vector contains non-finite entry: {x}")

    return float(math.hypot(*v))

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    diff: dict[int, int] = {}
    for s, e in intervals:
        diff[s] = diff.get(s, 0) + 1
        diff[e] = diff.get(e, 0) - 1

    max_load = 0
    earliest_t = 0
    current_load = 0

    for t in sorted(diff):
        current_load += diff[t]
        if current_load > max_load:
            max_load = current_load
            earliest_t = t

    return max_load, earliest_t

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"Error in row {i}: must be a tuple of length 3")

        category, amount, refunded = row

        if not isinstance(category, str) or len(category) == 0:
            raise ValueError(f"Error in row {i}: category must be a non-empty str")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"Error in row {i}: amount must be an int or float, not bool")

        if amount < 0:
            raise ValueError(f"Error in row {i}: amount must be >= 0")

        if not isinstance(refunded, bool):
            raise TypeError(f"Error in row {i}: refunded must be a bool")

        amt = float(amount)
        if category not in result:
            result[category] = {
                "count": 1,
                "gross": amt,
                "net": 0.0 if refunded else amt,
                "largest": amt,
            }
        else:
            entry = result[category]
            entry["count"] += 1
            entry["gross"] += amt
            if not refunded:
                entry["net"] += amt
            if amt > entry["largest"]:
                entry["largest"] = amt

    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    if (
        isinstance(low, bool)
        or not isinstance(low, (int, float))
        or isinstance(high, bool)
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    clamped = []
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"invalid item at index {i}")

        if item < low:
            clamped.append(low)
        elif item > high:
            clamped.append(high)
        else:
            clamped.append(item)

    return clamped

def flatten_depth(nested, max_depth):
    # Validation Rule 1
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")

    # Validation Rule 2
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")

    # Validation Rule 3
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Each entry in the stack tracks: [current_list, current_index, current_depth]
    stack = [[nested, 0, 0]]

    while stack:
        curr = stack[-1]
        lst, idx, depth = curr

        if idx >= len(lst):
            stack.pop()
            continue

        curr[1] += 1
        item = lst[idx]

        if isinstance(item, list) and depth < max_depth:
            stack.append([item, 0, depth + 1])
        else:
            result.append(item)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")

    if not text or text.isspace():
        raise ValueError("empty duration")

    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    last_idx = -1
    num_str = ""
    total_seconds = 0

    for c in text:
        if "0" <= c <= "9":
            num_str += c
        elif c in units:
            if not num_str:
                raise ValueError("malformed duration: unit missing digits")
            idx, multiplier = units[c]
            if idx <= last_idx:
                raise ValueError("malformed duration: components out of order or repeated")
            last_idx = idx
            total_seconds += int(num_str) * multiplier
            num_str = ""
        else:
            raise ValueError(f"malformed duration: invalid character {c!r}")

    if num_str:
        raise ValueError("malformed duration: trailing digits without unit")

    return total_seconds

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    out = []
    i = 0
    n = len(template)

    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                out.append('{')
                i += 2
                continue

            p = i
            j = i + 1
            if j >= n:
                raise ValueError("unclosed placeholder at position " + str(p))
            if template[j] == '}':
                raise ValueError("empty placeholder at position " + str(p))

            while j < n:
                ch = template[j]
                if ch == '}':
                    name = template[p + 1:j]
                    if name not in context:
                        raise KeyError(name)
                    out.append(str(context[name]))
                    i = j + 1
                    break
                elif ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ('0' <= ch <= '9') or ch == '_':
                    j += 1
                else:
                    raise ValueError("invalid placeholder at position " + str(p))
            else:
                raise ValueError("unclosed placeholder at position " + str(p))

        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                out.append('}')
                i += 2
                continue
            raise ValueError("stray '}' at position " + str(i))
        else:
            out.append(c)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        raise ValueError("empty expression")

    stack = []
    operators = {"+", "-", "*", "/"}

    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"token {i} must be a str")

        if tok in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            b = stack.pop()
            a = stack.pop()

            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            elif tok == "/":
                if b == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                sign = -1 if (a < 0) ^ (b < 0) else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            digits = tok[1:] if len(tok) > 0 and tok[0] in "+-" else tok
            if digits and all("0" <= c <= "9" for c in digits):
                stack.append(int(tok))
            else:
                raise ValueError(f"unknown token '{tok}' at token {i}")

    if len(stack) > 1:
        raise ValueError("leftover operands")

    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment in path")

    def _navigate(curr, segs):
        if not segs:
            return curr

        seg = segs[0]
        if isinstance(curr, dict):
            if seg not in curr:
                raise KeyError(f"Key not found: {seg}")
            next_node = curr[seg]
        elif isinstance(curr, list):
            s = seg[1:] if seg.startswith("-") else seg
            if not (len(s) > 0 and s.isascii() and s.isdigit()):
                raise ValueError(f"invalid index: {seg}")
            idx = int(seg)
            if idx < -len(curr) or idx >= len(curr):
                raise IndexError(f"Index out of range: {seg}")
            next_node = curr[idx]
        else:
            raise TypeError(f"cannot descend into type {type(curr).__name__}")

        return _navigate(next_node, segs[1:])

    return _navigate(data, segments)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    counts = {}
    for elem in items:
        if elem in counts:
            counts[elem] += 1
        else:
            counts[elem] = 1

    pairs = []
    for key, count in counts.items():
        pairs.append((key, count))

    # Stable insertion sort in descending order of counts
    for i in range(1, len(pairs)):
        current = pairs[i]
        j = i - 1
        while j >= 0 and current[1] > pairs[j][1]:
            pairs[j + 1] = pairs[j]
            j -= 1
        pairs[j + 1] = current

    return pairs[:k]
